div.script:
(function () {
    function ready(fn) {
        if (document.readyState !== 'loading') { fn(); }
        else { document.addEventListener('DOMContentLoaded', fn); }
    }
    ready(function () {
        var root = document.querySelector('.o_acpec_ft_distribution');
        if (!root) { return; }
        var currencyFallback = root.getAttribute('data-currency') || '';
        function numberValue(value) {
            var parsed = parseFloat(String(value || '0').replace(',', '.'));
            return isNaN(parsed) ? 0 : parsed;
        }
        function intValue(value) {
            var parsed = parseInt(value || '0', 10);
            return isNaN(parsed) ? 0 : parsed;
        }
        function fmtAmount(value) {
            return numberValue(value).toLocaleString(undefined, {minimumFractionDigits: 1, maximumFractionDigits: 1});
        }
        function visibleRows() {
            return Array.prototype.slice.call(root.querySelectorAll('.ft-line-row')).filter(function (row) {
                return row.style.display !== 'none';
            });
        }
        function updateMemberCard() {
            var select = root.querySelector('.ft-member-select');
            var card = root.querySelector('.ft-selected-member');
            if (!select || !card) { return; }
            var option = select.options[select.selectedIndex];
            if (!option || !option.value) {
                card.classList.add('d-none');
                return;
            }
            var name = option.getAttribute('data-name') || option.textContent.trim();
            var phone = option.getAttribute('data-phone') || '';
            var email = option.getAttribute('data-email') || '';
            card.querySelector('.ft-selected-member-avatar').textContent = (name || '?').trim().slice(0, 2).toUpperCase();
            card.querySelector('.ft-selected-member-name').textContent = name || '—';
            card.querySelector('.ft-selected-member-contact').textContent = [phone, email].filter(Boolean).join(' · ') || '—';
            card.classList.remove('d-none');
        }
        function updateLine(row) {
            var select = row.querySelector('.ft-carnet-select');
            var option = select && select.options[select.selectedIndex];
            if (!option || !option.value) {
                row.querySelector('.ft-line-tickets').textContent = '—';
                row.querySelector('.ft-line-carnets').textContent = '—';
                row.querySelector('.ft-line-amount').textContent = '0';
                row.querySelector('.ft-line-currency').textContent = currencyFallback;
                var emptyExpires = row.querySelector('.ft-line-expires');
                if (emptyExpires) { emptyExpires.textContent = '—'; }
                return {tickets: 0, carnets: 0, amount: 0, currency: currencyFallback};
            }
            var faceCount = intValue(option.getAttribute('data-face-count'));
            var ticketsAvailable = intValue(option.getAttribute('data-tickets')) || faceCount;
            var amountPerCarnet = numberValue(option.getAttribute('data-amount-per-carnet'));
            var currency = option.getAttribute('data-currency') || currencyFallback;
            var expiresAt = option.getAttribute('data-expires-at') || '—';
            row.querySelector('.ft-line-tickets').textContent = String(ticketsAvailable);
            row.querySelector('.ft-line-carnets').textContent = '1';
            row.querySelector('.ft-line-amount').textContent = fmtAmount(amountPerCarnet);
            row.querySelector('.ft-line-currency').textContent = currency;
            var expires = row.querySelector('.ft-line-expires');
            if (expires) { expires.textContent = expiresAt; }
            return {tickets: ticketsAvailable, carnets: 1, amount: amountPerCarnet, currency: currency};
        }
        function updateTotals() {
            var totals = {tickets: 0, carnets: 0, amount: 0, currency: currencyFallback};
            visibleRows().forEach(function (row) {
                var item = updateLine(row);
                totals.tickets += item.tickets;
                totals.carnets += item.carnets;
                totals.amount += item.amount;
                if (item.currency) { totals.currency = item.currency; }
            });
            var tickets = root.querySelector('.ft-total-tickets');
            var carnets = root.querySelector('.ft-total-carnets');
            var amount = root.querySelector('.ft-total-amount');
            var currency = root.querySelector('.ft-total-currency');
            if (tickets) { tickets.textContent = String(totals.tickets); }
            if (carnets) { carnets.textContent = String(totals.carnets); }
            if (amount) { amount.textContent = fmtAmount(totals.amount); }
            if (currency) { currency.textContent = totals.currency; }
        }
        root.querySelectorAll('.ft-carnet-select, .ft-line-qty').forEach(function (el) {
            el.addEventListener('change', updateTotals);
            el.addEventListener('input', updateTotals);
        });
        var memberSelect = root.querySelector('.ft-member-select');
        if (memberSelect) { memberSelect.addEventListener('change', updateMemberCard); }
        var addLine = root.querySelector('.ft-add-line');
        if (addLine) {
            addLine.addEventListener('click', function () {
                var hidden = Array.prototype.slice.call(root.querySelectorAll('.ft-line-row')).find(function (row) {
                    return row.style.display === 'none';
                });
                if (hidden) {
                    hidden.style.display = '';
                    hidden.querySelector('.ft-carnet-select').focus();
                }
                updateTotals();
            });
        }
        root.querySelectorAll('.ft-remove-line').forEach(function (button) {
            button.addEventListener('click', function () {
                var row = button.closest('.ft-line-row');
                if (!row) { return; }
                row.querySelectorAll('select, input').forEach(function (el) { el.value = ''; });
                if (visibleRows().length > 1) { row.style.display = 'none'; }
                updateTotals();
            });
        });
        updateMemberCard();
        updateTotals();
    });
})();
